From a471761d866b8e02f0143a83c1842d02f9e35184 Mon Sep 17 00:00:00 2001
From: Paul Cercueil <paul.cercueil@analog.com>
Date: Mon, 19 Dec 2016 12:27:25 +0100
Subject: [PATCH] Local backend: Fix extended name not handled in scan-element
 attrs

Since the scan-element attributes are now hidden, they wouldn't get added
to the iio_channel's list of attributes, and as such didn't take part in
the extended name calculation.

Worse, the current code would fail when the scan-element attributes had
an extended name in their filename.

This commit changes this behaviour, so that the scan-element attributes
are first added in a separate list of attributes (in iio_channel_pdata).
The set_channel_name() function will then use the two lists of
attributes for the extended name calculation. Finally, this list is
freed as it doesn't have any use after the scan-element attributes are
parsed correctly.

This fixes a bug introduced by 9d77ca0.
Fixes #73.

Signed-off-by: Paul Cercueil <paul.cercueil@analog.com>

diff --git a/local.c b/local.c
index 2214b74d..47f298c5 100644
--- a/local.c
+++ b/local.c
@@ -100,6 +100,8 @@ struct iio_device_pdata {

 struct iio_channel_pdata {
 	char *enable_fn;
+	struct iio_channel_attr *protected_attrs;
+	unsigned int nb_protected_attrs;
 };

 static const char * const device_attrs_blacklist[] = {
@@ -167,15 +169,19 @@ static void strcut(char *str, int nb)

 static int set_channel_name(struct iio_channel *chn)
 {
+	struct iio_channel_pdata *pdata = chn->pdata;
 	size_t prefix_len = 0;
 	const char *attr0;
 	const char *ptr;
 	unsigned int i;

-	if (chn->nb_attrs < 2)
+	if (chn->nb_attrs + pdata->nb_protected_attrs < 2)
 		return 0;

-	attr0 = ptr = chn->attrs[0].name;
+	if (chn->nb_attrs)
+		attr0 = ptr = chn->attrs[0].name;
+	else
+		attr0 = ptr = pdata->protected_attrs[0].name;

 	while (true) {
 		bool can_fix = true;
@@ -189,6 +195,12 @@ static int set_channel_name(struct iio_channel *chn)
 		for (i = 1; can_fix && i < chn->nb_attrs; i++)
 			can_fix = !strncmp(attr0, chn->attrs[i].name, len);

+		for (i = !chn->nb_attrs;
+				can_fix && i < pdata->nb_protected_attrs; i++) {
+			can_fix = !strncmp(attr0,
+					pdata->protected_attrs[i].name, len);
+		}
+
 		if (!can_fix)
 			break;

@@ -210,6 +222,8 @@ static int set_channel_name(struct iio_channel *chn)
 		/* Shrink the attribute name */
 		for (i = 0; i < chn->nb_attrs; i++)
 			strcut(chn->attrs[i].name, prefix_len);
+		for (i = 0; i < pdata->nb_protected_attrs; i++)
+			strcut(pdata->protected_attrs[i].name, prefix_len);
 	}

 	return 0;
@@ -1148,6 +1162,54 @@ static int handle_protected_scan_element_attr(struct iio_channel *chn,
 	return 0;
 }

+static int handle_scan_elements(struct iio_channel *chn)
+{
+	struct iio_channel_pdata *pdata = chn->pdata;
+	unsigned int i;
+
+	for (i = 0; i < pdata->nb_protected_attrs; i++) {
+		int ret = handle_protected_scan_element_attr(chn,
+				pdata->protected_attrs[i].name,
+				pdata->protected_attrs[i].filename);
+		if (ret < 0)
+			return ret;
+	}
+
+	return 0;
+}
+
+static int add_protected_attr(struct iio_channel *chn, char *name, char *fn)
+{
+	struct iio_channel_pdata *pdata = chn->pdata;
+	struct iio_channel_attr *attrs;
+
+	attrs = realloc(pdata->protected_attrs,
+			(1 + pdata->nb_protected_attrs) * sizeof(*attrs));
+	if (!attrs)
+		return -ENOMEM;
+
+	attrs[pdata->nb_protected_attrs].name = name;
+	attrs[pdata->nb_protected_attrs++].filename = fn;
+	pdata->protected_attrs = attrs;
+
+	DEBUG("Add protected attr \'%s\' to channel \'%s\'\n", name, chn->id);
+	return 0;
+}
+
+static void free_protected_attrs(struct iio_channel *chn)
+{
+	struct iio_channel_pdata *pdata = chn->pdata;
+	unsigned int i;
+
+	for (i = 0; i < pdata->nb_protected_attrs; i++) {
+		free(pdata->protected_attrs[i].name);
+		free(pdata->protected_attrs[i].filename);
+	}
+
+	free(pdata->protected_attrs);
+	pdata->nb_protected_attrs = 0;
+}
+
 static int add_attr_to_channel(struct iio_channel *chn,
 		const char *attr, const char *path, bool is_scan_element)
 {
@@ -1156,17 +1218,19 @@ static int add_attr_to_channel(struct iio_channel *chn,
 	if (!name)
 		return -ENOMEM;

-	if (is_scan_element) {
-		int ret = handle_protected_scan_element_attr(chn, name, path);
-
-		free(name);
-		return ret;
-	}
-
 	fn = iio_strdup(path);
 	if (!fn)
 		goto err_free_name;

+	if (is_scan_element) {
+		int ret = add_protected_attr(chn, name, fn);
+
+		if (ret < 0)
+			goto err_free_fn;
+
+		return 0;
+	}
+
 	attrs = realloc(chn->attrs, (1 + chn->nb_attrs) *
 			sizeof(struct iio_channel_attr));
 	if (!attrs)
@@ -1539,10 +1603,17 @@ static int create_device(void *d, const char *path)

 	ret = add_scan_elements(dev, path);
 	if (ret < 0)
-		goto err_free_device;
+		goto err_free_scan_elements;

-	for (i = 0; i < dev->nb_channels; i++)
-		set_channel_name(dev->channels[i]);
+	for (i = 0; i < dev->nb_channels; i++) {
+		struct iio_channel *chn = dev->channels[i];
+
+		set_channel_name(chn);
+		ret = handle_scan_elements(chn);
+		free_protected_attrs(chn);
+		if (ret < 0)
+			goto err_free_scan_elements;
+	}

 	ret = detect_and_move_global_attrs(dev);
 	if (ret < 0)
@@ -1563,6 +1634,9 @@ static int create_device(void *d, const char *path)
 	if (!ret)
 		return 0;

+err_free_scan_elements:
+	for (i = 0; i < dev->nb_channels; i++)
+		free_protected_attrs(dev->channels[i]);
 err_free_device:
 	local_free_pdata(dev);
 	free_device(dev);
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the scan-element attributes being hidden and not added to the `iio_channel`'s list of attributes, which led to failures in the extended name calculation when these attributes had an extended name in their filename. The existing code did not account for these attributes, resulting in incorrect behavior when processing them.

        Commit message:
        Local backend: Fix extended name not handled in scan-element
 attrs

Since the scan-element attributes are now hidden, they wouldn't get added
to the iio_channel's list of attributes, and as such didn't take part in
the extended name calculation.

Worse, the current code would fail when the scan-element attributes had
an extended name in their filename.

This commit changes this behaviour, so that the scan-element attributes
are first added in a separate list of attributes (in iio_channel_pdata).
The set_channel_name() function will then use the two lists of
attributes for the extended name calculation. Finally, this list is
freed as it doesn't have any use after the scan-element attributes are
parsed correctly.

This fixes a bug introduced by 9d77ca0.
Fixes #73.

Signed-off-by: Paul Cercueil <paul.cercueil@analog.com>  

        Patch:
         struct iio_channel_pdata {
 	char *enable_fn;
+	struct iio_channel_attr *protected_attrs;
+	unsigned int nb_protected_attrs;
 };


 static int set_channel_name(struct iio_channel *chn)
 {
+	struct iio_channel_pdata *pdata = chn->pdata;
 	size_t prefix_len = 0;
 	const char *attr0;
 	const char *ptr;
 	unsigned int i;

-	if (chn->nb_attrs < 2)
+	if (chn->nb_attrs + pdata->nb_protected_attrs < 2)
 		return 0;

-	attr0 = ptr = chn->attrs[0].name;
+	if (chn->nb_attrs)
+		attr0 = ptr = chn->attrs[0].name;
+	else
+		attr0 = ptr = pdata->protected_attrs[0].name;

 	while (true) {
 		bool can_fix = true;
 		size_t len;

 		ptr = strchr(ptr, '_');
 		if (!ptr)
 			break;

 		len = ptr - attr0 + 1;
 		for (i = 1; can_fix && i < chn->nb_attrs; i++)
 			can_fix = !strncmp(attr0, chn->attrs[i].name, len);

+		for (i = !chn->nb_attrs;
+				can_fix && i < pdata->nb_protected_attrs; i++) {
+			can_fix = !strncmp(attr0,
+					pdata->protected_attrs[i].name, len);
+		}
+
 		if (!can_fix)
 			break;

 		prefix_len = len;
 		ptr = ptr + 1;
 	}

 	if (prefix_len) {
 		char *name;

 		name = malloc(prefix_len);
 		if (!name)
 			return -ENOMEM;
 		strncpy(name, attr0, prefix_len - 1);
 		name[prefix_len - 1] = '\0';
 		DEBUG("Setting name of channel %s to %s\n", chn->id, name);
 		chn->name = name;

 		/* Shrink the attribute name */
 		for (i = 0; i < chn->nb_attrs; i++)
 			strcut(chn->attrs[i].name, prefix_len);
+		for (i = 0; i < pdata->nb_protected_attrs; i++)
+			strcut(pdata->protected_attrs[i].name, prefix_len);
 	}

 	return 0;
 }


+static int handle_scan_elements(struct iio_channel *chn)
+{
+	struct iio_channel_pdata *pdata = chn->pdata;
+	unsigned int i;
+
+	for (i = 0; i < pdata->nb_protected_attrs; i++) {
+		int ret = handle_protected_scan_element_attr(chn,
+				pdata->protected_attrs[i].name,
+				pdata->protected_attrs[i].filename);
+		if (ret < 0)
+			return ret;
+	}
+
+	return 0;
+}
+
+static int add_protected_attr(struct iio_channel *chn, char *name, char *fn)
+{
+	struct iio_channel_pdata *pdata = chn->pdata;
+	struct iio_channel_attr *attrs;
+
+	attrs = realloc(pdata->protected_attrs,
+			(1 + pdata->nb_protected_attrs) * sizeof(*attrs));
+	if (!attrs)
+		return -ENOMEM;
+
+	attrs[pdata->nb_protected_attrs].name = name;
+	attrs[pdata->nb_protected_attrs++].filename = fn;
+	pdata->protected_attrs = attrs;
+
+	DEBUG("Add protected attr \'%s\' to channel \'%s\'\n", name, chn->id);
+	return 0;
+}
+
+static void free_protected_attrs(struct iio_channel *chn)
+{
+	struct iio_channel_pdata *pdata = chn->pdata;
+	unsigned int i;
+
+	for (i = 0; i < pdata->nb_protected_attrs; i++) {
+		free(pdata->protected_attrs[i].name);
+		free(pdata->protected_attrs[i].filename);
+	}
+
+	free(pdata->protected_attrs);
+	pdata->nb_protected_attrs = 0;
+}
+
 static int add_attr_to_channel(struct iio_channel *chn,
 		const char *attr, const char *path, bool is_scan_element)
 {
 	struct iio_channel_attr *attrs;
 	char *fn, *name = get_short_attr_name(chn, attr);
 	if (!name)
 		return -ENOMEM;

-	if (is_scan_element) {
-		int ret = handle_protected_scan_element_attr(chn, name, path);
-
-		free(name);
-		return ret;
-	}
-
 	fn = iio_strdup(path);
 	if (!fn)
 		goto err_free_name;

+	if (is_scan_element) {
+		int ret = add_protected_attr(chn, name, fn);
+
+		if (ret < 0)
+			goto err_free_fn;
+
+		return 0;
+	}
+
 	attrs = realloc(chn->attrs, (1 + chn->nb_attrs) *
 			sizeof(struct iio_channel_attr));
 	if (!attrs)
 		goto err_free_fn;

 	attrs[chn->nb_attrs].filename = fn;
 	attrs[chn->nb_attrs++].name = name;
 	chn->attrs = attrs;
 	DEBUG("Added attr \'%s\' to channel \'%s\'\n", name, chn->id);
 	return 0;

 err_free_fn:
 	free(fn);
 err_free_name:
 	free(name);
 	return -ENOMEM;
 }


 static int create_device(void *d, const char *path)
 {
 	uint32_t *mask = NULL;
 	unsigned int i;
 	int ret;
 	struct iio_context *ctx = d;
 	struct iio_device *dev = zalloc(sizeof(*dev));
 	if (!dev)
 		return -ENOMEM;

 	dev->pdata = zalloc(sizeof(*dev->pdata));
 	if (!dev->pdata) {
 		free(dev);
 		return -ENOMEM;
 	}

 	dev->pdata->fd = -1;
 	dev->pdata->blocking = true;
 	dev->pdata->nb_blocks = NB_BLOCKS;

 	dev->ctx = ctx;
 	dev->id = iio_strdup(strrchr(path, '/') + 1);
 	if (!dev->id) {
 		local_free_pdata(dev);
 		free(dev);
 		return -ENOMEM;
 	}

 	ret = foreach_in_dir(dev, path, false, add_attr_or_channel);
 	if (ret < 0)
 		goto err_free_device;

 	ret = add_scan_elements(dev, path);
 	if (ret < 0)
-		goto err_free_device;
+		goto err_free_scan_elements;

-	for (i = 0; i < dev->nb_channels; i++)
-		set_channel_name(dev->channels[i]);
+	for (i = 0; i < dev->nb_channels; i++) {
+		struct iio_channel *chn = dev->channels[i];
+
+		set_channel_name(chn);
+		ret = handle_scan_elements(chn);
+		free_protected_attrs(chn);
+		if (ret < 0)
+			goto err_free_scan_elements;
+	}

 	ret = detect_and_move_global_attrs(dev);
 	if (ret < 0)
 		goto err_free_device;

 	dev->words = (dev->nb_channels + 31) / 32;
 	if (dev->words) {
 		mask = calloc(dev->words, sizeof(*mask));
 		if (!mask) {
 			ret = -ENOMEM;
 			goto err_free_device;
 		}
 	}

 	dev->mask = mask;

 	ret = add_device_to_context(ctx, dev);
 	if (!ret)
 		return 0;

+err_free_scan_elements:
+	for (i = 0; i < dev->nb_channels; i++)
+		free_protected_attrs(dev->channels[i]);
 err_free_device:
 	local_free_pdata(dev);
 	free_device(dev);
 	return ret;
 }



